B.cPU=new A.cp("\u0627\u0644\u0643\u062b\u0627\u0641\u0629 \u0644\u0627\u0632\u0645 \u062a\u0643\u0648\u0646 \u0623\u0643\u0628\u0631 \u0645\u0646 \u0635\u0641\u0631","Density must be greater than zero")
B.cPV=new A.cp("\u0627\u0644\u0623\u0646\u0628\u0648\u0628 \u0644\u0627\u0632\u0645 \u064a\u0643\u0648\u0646 \u0623\u0635\u063a\u0631 \u0645\u0646 \u0627\u0644\u0628\u0626\u0631","The pipe must be smaller than the hole")
B.acM=new A.cp("\u0627\u0644\u0623\u0646\u0628\u0648\u0628 \u0627\u0644\u062f\u0627\u062e\u0644\u064a \u0644\u0627\u0632\u0645 \u064a\u0643\u0648\u0646 \u0623\u0635\u063a\u0631 \u0645\u0646 \u0627\u0644\u062e\u0627\u0631\u062c\u064a","The inner pipe must be smaller than the outer one")
B.cPW=new A.cp("\u0627\u0644\u0623\u0646\u0627\u0628\u064a\u0628 \u0644\u0627\u0632\u0645 \u062a\u0643\u0648\u0646 \u0623\u0635\u063a\u0631 \u0645\u0646 \u0627\u0644\u0628\u0626\u0631","The pipe must be smaller than the hole")
B.cPX=new A.cp("\u0645\u0627\u0643\u0648 \u0647\u0630\u0627 \u0627\u0644\u062d\u062c\u0645 \u0628\u0647\u0630\u0627 \u0627\u0644\u0646\u0648\u0639. \u063a\u064a\u0651\u0631 \u0627\u0644\u0646\u0648\u0639 \u0623\u0648 \u0627\u062e\u062a\u0631 \u0627\u0644\u062d\u062c\u0645 \u0645\u0646 \u0627\u0644\u062c\u062f\u0648\u0644.","No such size for this pipe type. Change the type or pick the size from the table.")
B.cPY=new A.cp("\u0644\u0627\u0632\u0645 KOP < \u0646\u0647\u0627\u064a\u0629 \u0627\u0644\u0625\u0633\u0642\u0627\u0637 \u2264 \u0627\u0644\u0647\u062f\u0641","KOP < end of drop \u2264 target is required")
B.cPZ=new A.cp("\u0627\u0644\u0625\u0632\u0627\u062d\u0629 \u0643\u0628\u064a\u0631\u0629: \u0627\u0644\u0645\u064a\u0644 \u064a\u062a\u062c\u0627\u0648\u0632 90\xb0","Displacement too large: inclination exceeds 90\xb0")
B.cQ_=new A.cp("\u0627\u0644\u0641\u0627\u0635\u0644 \u0643\u0628\u064a\u0631 \u0644\u062f\u0631\u062c\u0629 \u0627\u0644\u0625\u0632\u0627\u062d\u0629 \u062a\u0635\u064a\u0631 \u0633\u0627\u0644\u0628\u0629","The spacer is so large that the displacement becomes negative")
B.cQ0=new A.cp("\u0627\u0644\u0642\u064a\u0645 \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u062f\u0649","Values out of range")
B.cQ1=new A.cp("\u0627\u0644\u0643\u0641\u0627\u0621\u0629 \u0644\u0627\u0632\u0645 \u062a\u0643\u0648\u0646 \u0623\u0643\u0628\u0631 \u0645\u0646 0 \u0648\u0644\u062d\u062f 100%","Efficiency must be above 0 and at most 100%")
B.acN=new A.cp("\u0627\u0644\u0647\u062f\u0641 \u0644\u0627\u0632\u0645 \u064a\u0643\u0648\u0646 \u0623\u0639\u0645\u0642 \u0645\u0646 KOP","The target must be deeper than the KOP")
B.cQ2=new A.cp("\u0627\u0644\u0633\u0639\u0629 \u0644\u0627\u0632\u0645 \u062a\u0643\u0648\u0646 \u0623\u0643\u0628\u0631 \u0645\u0646 \u0635\u0641\u0631","Capacity must be greater than zero")
B.cQ3=new A.cp("\u0627\u0644\u0642\u0637\u0631 \u0627\u0644\u062e\u0627\u0631\u062c\u064a \u0644\u0644\u0623\u0646\u0628\u0648\u0628 \u0644\u0627\u0632\u0645 \u064a\u0643\u0648\u0646 \u0623\u0635\u063a\u0631 \u0645\u0646 \u0642\u0637\u0631 \u0627\u0644\u0628\u0626\u0631","Pipe OD must be smaller than the hole size")
B.cQ4=new A.cp("\u0627\u0644\u0634\u062f \u0623\u0643\u0628\u0631 \u0645\u0646 \u0645\u0642\u0627\u0648\u0645\u0629 \u062c\u0633\u0645 \u0627\u0644\u0623\u0646\u0628\u0648\u0628","Tension exceeds the pipe-body yield strength")
B.acO=new A.cp("\u0642\u0631\u0627\u0621\u0629 600 \u0644\u0627\u0632\u0645 \u062a\u0643\u0648\u0646 \u0623\u0643\u0628\u0631 \u0645\u0646 \u0642\u0631\u0627\u0621\u0629 300","The 600 rpm reading must be above the 300 rpm reading")
B.AF=new A.cp("\u0645\u0633\u062a\u0648\u0649 \u0627\u0644\u0633\u0627\u0626\u0644 \u0623\u0639\u0644\u0649 \u0645\u0646 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u062e\u0632\u0627\u0646","Fluid level is above the tank height")
B.cQ5=new A.cp("\u0627\u0644\u0642\u064a\u0645 \u062e\u0627\u0631\u062c \u0645\u062f\u0649 \u0627\u0644\u0645\u0639\u0627\u062f\u0644\u0629: \u0644\u0627\u0632\u0645 12W/(10\u2076 d_b) \u0648 R/(60N) \u0623\u0642\u0644 \u0645\u0646 1","Outside the formula range: 12W/(10\u2076 d_b) and R/(60N) must be below 1")
B.cQ6=new A.cp("\u0627\u062e\u062a\u0627\u0631 \u0627\u0644\u0637\u0631\u064a\u0642\u0629 \u0645\u0646 \u0627\u0644\u0642\u0627\u0626\u0645\u0629","Pick the method from the list")
B.cQ7=new A.cp("\u0627\u0644\u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0644\u0627\u0632\u0645 \u064a\u0643\u0648\u0646 \u0623\u0642\u0644 \u0645\u0646 \u062a\u0631\u0643\u064a\u0632 \u0627\u0644\u062d\u0627\u0645\u0636 \u0627\u0644\u0645\u0631\u0643\u0632","The target strength must be below the stock strength")
B.cQ8=new A.cp("\u0627\u0644\u0648\u0632\u0646 \u0643\u0628\u064a\u0631 \u0639\u0644\u0649 \u0647\u0630\u0627 \u0627\u0644\u0642\u0637\u0631","The weight is too large for this OD")
B.cQ9=new A.cp("\u0627\u0644\u0647\u062f\u0641 \u0642\u0631\u064a\u0628 \u0643\u0644\u0634 \u0644\u0647\u0630\u0627 \u0627\u0644\u0645\u0639\u062f\u0644: \u0642\u0644\u0644 \u0627\u0644\u0640 KOP \u0623\u0648 \u0632\u064a\u062f \u0645\u0639\u062f\u0644 \u0627\u0644\u0628\u0646\u0627\u0621","Target too close for this rate: lower the KOP or raise the build rate")
B.acP=new A.cp("\u0642\u0637\u0631 \u0627\u0644\u0639\u0645\u0648\u062f \u0644\u0627\u0632\u0645 \u064a\u0643\u0648\u0646 \u0623\u0635\u063a\u0631 \u0645\u0646 \u0642\u0637\u0631 \u0627\u0644\u0628\u0637\u0627\u0646\u0629","Rod diameter must be smaller than the liner")
B.cQa=new A.cp("\u0627\u0644\u0645\u064a\u0644 \u0644\u0627\u0632\u0645 \u064a\u0643\u0648\u0646 \u0628\u064a\u0646 0 \u0648 90 \u062f\u0631\u062c\u0629 (\u0627\u0644\u0645\u0639\u0627\u062f\u0644\u0629 \u0645\u0627 \u062a\u0646\u0637\u0628\u0642 \u0639\u0644\u0649 \u0627\u0644\u0628\u0626\u0631 \u0627\u0644\u0639\u0645\u0648\u062f\u064a)","Inclination must be above 0\xb0 and at most 90\xb0 (not valid for vertical holes)")
B.cQb=new A.cp("\u0627\u0644\u0645\u064a\u0644 \u0627\u0644\u0646\u0647\u0627\u0626\u064a \u0628\u064a\u0646 0 \u0648 90\xb0","The final inclination must be 0\u201390\xb0")
